// SOLIDWORKS Simulation heat-transfer studies for the VTOL heat sources (lift unit, pod, pusher).
// Inputs: cad/params.txt (geometry) and analysis/thermal/thermal_inputs.json (heat loads, film
// coefficients, materials — generated by analysis/thermal/thermal_inputs.py from analysis/results.json
// and the sources listed in docs/research/thermal.md). Outputs: cad/sim/thermal/*.SLDPRT (studies saved
// inside), cad/sim/thermal/fields/*.json (nodes, surface triangles, nodal temperatures per case and step),
// cad/sim/thermal/results.txt. Does not touch cad/Sim.cs or cad/model/.
// Usage: Thermal.exe cad\params.txt analysis\thermal\thermal_inputs.json cad\sim\thermal [probe]
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.Globalization;
using SolidWorks.Interop.sldworks;
using SolidWorks.Interop.swconst;
using SolidWorks.Interop.cosworks;

class Thermal
{
    static SldWorks sw; static CosmosWorks cw;
    static Dictionary<string, string> P = new Dictionary<string, string>();
    static Dictionary<string, double> J = new Dictionary<string, double>();   // flat numeric inputs from thermal_inputs.json
    static string Out, PartTpl; static StreamWriter R;
    static CultureInfo IC = CultureInfo.InvariantCulture;
    const string Lib = @"C:\Program Files\SOLIDWORKS Corp\SOLIDWORKS\lang\english\sldmaterials\solidworks materials.sldmat";
    static double D(string k) { return double.Parse(P[k], IC); }
    static double I(string k) { if (!J.ContainsKey(k)) throw new Exception("input missing: " + k); return J[k]; }
    static void Res(string k, double v, string unit, string note)
    {
        string s = string.Format(IC, "{0}={1:G6}|{2}|{3}", k, v, unit, note);
        Console.WriteLine(s); R.WriteLine(s); R.Flush();
    }
    static void Log(string s) { Console.WriteLine(s); }

    static int Main(string[] a)
    {
        P = ParamsFile.Load(a[0]).P;   // cad/Shared.cs: the one params.txt reader (compile with Shared.cs, see cad/README.md)
        LoadFlatJson(a[1]);
        Out = Path.GetFullPath(a[2]); Directory.CreateDirectory(Out); Directory.CreateDirectory(Path.Combine(Out, "fields"));
        bool probe = a.Length > 3 && a[3] == "probe";
        R = new StreamWriter(Path.Combine(Out, "results.txt"), a.Length > 3 && a[3] != "probe" && !a[3].Contains("M"));   // append when re-running a subset
        R.WriteLine("# SOLIDWORKS Simulation thermal results, key=value|unit|note  (generated " + DateTime.Now.ToString("yyyy-MM-dd HH:mm", IC) + ")");
        sw = (SldWorks)Activator.CreateInstance(Type.GetTypeFromProgID("SldWorks.Application"));
        sw.Visible = true;
        sw.LoadAddIn(@"C:\Program Files\SOLIDWORKS Corp\SOLIDWORKS\Simulation\cosworks.dll");
        object cb = sw.GetAddInObject("SldWorks.Simulation");
        for (int i = 0; i < 30 && cb == null; i++)
        {
            System.Threading.Thread.Sleep(3000);
            int st = sw.LoadAddIn(@"C:\Program Files\SOLIDWORKS Corp\SOLIDWORKS\Simulation\cosworks.dll");
            cb = sw.GetAddInObject("SldWorks.Simulation");
            Console.WriteLine("waiting for Simulation add-in (LoadAddIn=" + st + ")");
        }
        if (cb == null) throw new Exception("Simulation add-in unavailable");
        cw = ((CwAddincallback)cb).CosmosWorks;
        PartTpl = sw.GetUserPreferenceStringValue((int)swUserPreferenceStringValue_e.swDefaultTemplatePart);
        if (probe) { Probe(); R.Close(); return 0; }
        string which = a.Length > 3 ? a[3] : "MLPK";
        if (which.Contains("M")) MotorOnly();
        if (which.Contains("L")) LiftUnit();
        if (which.Contains("P")) Pod();
        if (which.Contains("K")) Pusher();
        R.Close();
        return 0;
    }

    // ---------------- minimal flat JSON reader: "key": number at any depth, keys joined with '.' ----------------
    static void LoadFlatJson(string file)
    {
        string s = File.ReadAllText(file); var path = new List<string>(); int i = 0; string key = null;
        while (i < s.Length)
        {
            char c = s[i];
            if (c == '"') { int e = s.IndexOf('"', i + 1); string tok = s.Substring(i + 1, e - i - 1); i = e + 1;
                int j = i; while (j < s.Length && char.IsWhiteSpace(s[j])) j++;
                if (j < s.Length && s[j] == ':') { key = tok; i = j + 1; } continue; }
            if (c == '{') { if (key != null) path.Add(key); else if (path.Count > 0 || i > 0) path.Add(""); key = null; i++; continue; }
            if (c == '}') { if (path.Count > 0) path.RemoveAt(path.Count - 1); key = null; i++; continue; }
            if ((c == '-' || char.IsDigit(c)) && key != null)
            {
                int e = i; while (e < s.Length && (char.IsDigit(s[e]) || "-+.eE".IndexOf(s[e]) >= 0)) e++;
                double v; if (double.TryParse(s.Substring(i, e - i), NumberStyles.Float, IC, out v))
                { var full = new List<string>(); foreach (string p in path) if (p.Length > 0) full.Add(p); full.Add(key); J[string.Join(".", full.ToArray())] = v; }
                key = null; i = e; continue;
            }
            i++;
        }
    }

    // ---------------- geometry helpers (same pattern as Sim.cs) ----------------
    static ModelDoc2 NewPart() { return (ModelDoc2)sw.NewDocument(PartTpl, 0, 0, 0); }
    static void Sk(ModelDoc2 d, string plane)
    {
        d.ClearSelection2(true);
        d.Extension.SelectByID2(plane, "PLANE", 0, 0, 0, false, 0, null, 0);
        d.SketchManager.InsertSketch(true); d.SketchManager.AddToDB = true;
    }
    static void EndSk(ModelDoc2 d)
    {
        d.SketchManager.AddToDB = false; d.SketchManager.InsertSketch(true);
        d.ClearSelection2(true); ((Feature)d.FeatureByPositionReverse(0)).Select2(false, 0);
    }
    // extrude the last sketch so the new body spans [lo, hi] along axis (0 X, 1 Y, 2 Z); the sketch plane sits at 0 on that axis.
    // Tries the direction flags until the body box matches (the API's Dir/offset semantics are probed, as BuildVtol.cs does for cuts).
    static void Ext(ModelDoc2 d, int axis, double lo, double hi, bool merge, string name)
    {
        bool straddle = lo < -1e-9 && hi > 1e-9;
        double depth = hi - lo, off = straddle ? 0 : Math.Min(Math.Abs(lo), Math.Abs(hi));
        foreach (bool flip in new[] { false, true }) foreach (bool flipOff in new[] { false, true })
        {
            ReSelectSketch(d);
            bool symmetric = straddle && Math.Abs(hi + lo) < 1e-6;
            Feature f = symmetric
                ? d.FeatureManager.FeatureExtrusion3(true, false, false, 6, 0, depth, 0, false, false, false, false, 0, 0, false, false, false, false, merge, true, true, 0, 0, false)   // 6 = mid-plane
                : straddle
                ? d.FeatureManager.FeatureExtrusion3(false, false, flip, 0, 0, flip ? -lo : hi, flip ? hi : -lo, false, false, false, false, 0, 0, false, false, false, false, merge, true, true, 0, 0, false)   // double-ended blind
                : d.FeatureManager.FeatureExtrusion3(true, false, flip, 0, 0, depth, 0, false, false, false, false,
                0, 0, false, false, false, false, merge, true, true, off > 1e-9 ? (int)swStartConditions_e.swStartOffset : 0, off, flipOff);
            if (f == null) continue;
            d.EditRebuild3();
            Body2[] bs = Bodies(d); Body2 nb2 = null;
            foreach (Body2 b in bs) { double[] bx = (double[])b.GetBodyBox(); if (Math.Abs(bx[axis] - lo) < 5e-4 && Math.Abs(bx[axis + 3] - hi) < 5e-4) nb2 = b; }
            if (nb2 != null) { f.Name = name; Log("  " + name + " ok " + Box(nb2)); return; }
            if (merge && bs.Length == 1) { double[] bx = (double[])bs[0].GetBodyBox(); if (bx[axis] <= lo + 5e-4 && bx[axis + 3] >= hi - 5e-4) { f.Name = name; return; } }
            Log("  " + name + ": flip " + flip + "/" + flipOff + " gave " + string.Join(" | ", Array.ConvertAll(bs, b => Box(b))) + "; retrying");
            f.Select2(false, 0); d.EditDelete();
            if (off < 1e-9) break;   // without an offset only `flip` matters
        }
        throw new Exception("extrude " + name + " could not be placed at [" + lo + "," + hi + "]");
    }
    static void ReSelectSketch(ModelDoc2 d) { d.ClearSelection2(true); ((Feature)d.FeatureByPositionReverse(0)).Select2(false, 0); }
    static string Box(Body2 b) { double[] bx = (double[])b.GetBodyBox(); return b.Name + "[" + string.Join(",", Array.ConvertAll(bx, x => (x * 1000).ToString("0.#", IC))) + "]"; }
    static double Vol(ModelDoc2 d) { d.EditRebuild3(); MassProperty mp = d.Extension.CreateMassProperty(); return mp == null ? 0 : mp.Volume; }
    static double Com(ModelDoc2 d, int axis) { MassProperty mp = d.Extension.CreateMassProperty(); return ((double[])mp.CenterOfMass)[axis]; }
    // cut the sketch profile between lo and hi along axis (sketch plane at 0): start offset + blind depth; direction probed by the
    // removed volume and the sign of the centroid shift (a slab removed below the centroid moves it up)
    static void CutRange(ModelDoc2 d, int axis, double lo, double hi, string name)
    {
        double v0 = Vol(d), c0 = Com(d, axis), depth = hi - lo, off = Math.Min(Math.Abs(lo), Math.Abs(hi)), cSlab = (lo + hi) / 2;
        foreach (bool flip in new[] { false, true }) foreach (bool flipOff in new[] { false, true })
        {
            ReSelectSketch(d);
            Feature f = d.FeatureManager.FeatureCut4(true, false, flip, 0, 0, depth, 0, false, false, false, false, 0, 0,
                false, false, false, false, false, true, true, true, true, false, off > 1e-9 ? (int)swStartConditions_e.swStartOffset : 0, off, flipOff, false);
            if (f == null) continue;
            double v1 = Vol(d), c1 = Com(d, axis);
            bool removed = v1 < v0 - 1e-9, side = (c1 - c0) * (cSlab - c0) < 0 || Math.Abs(cSlab - c0) < 1e-6;
            if (removed && side) { f.Name = name; Log("  cut " + name + " removed " + ((v0 - v1) * 1e6).ToString("0.0", IC) + " cm3 (flip " + flip + "/" + flipOff + ", centroid shift " + ((c1 - c0) * 1000).ToString("0.##", IC) + " mm)"); return; }
            Log("  cut " + name + ": flip " + flip + "/" + flipOff + " removed " + ((v0 - v1) * 1e6).ToString("0.0", IC) + " cm3, shift " + ((c1 - c0) * 1000).ToString("0.##", IC) + " mm; retrying");
            f.Select2(false, 0); d.EditDelete();
            if (off < 1e-9) break;
        }
        throw new Exception("cut " + name + " could not be placed at [" + lo + "," + hi + "]");
    }
    static void Rect(ModelDoc2 d, double x0, double y0, double x1, double y1) { d.SketchManager.CreateCornerRectangle(x0, y0, 0, x1, y1, 0); }
    static void Circ(ModelDoc2 d, double x, double y, double r) { d.SketchManager.CreateCircleByRadius(x, y, 0, r); }
    static Body2[] Bodies(ModelDoc2 d)
    {
        object[] bs = (object[])((PartDoc)d).GetBodies2((int)swBodyType_e.swSolidBody, true);
        var list = new List<Body2>(); foreach (object b in bs) list.Add((Body2)b); return list.ToArray();
    }
    static Body2 Body(ModelDoc2 d, string name) { foreach (Body2 b in Bodies(d)) if (b.Name == name) return b; throw new Exception("body not found " + name); }
    static List<Face2> FacesOf(Body2 b) { var l = new List<Face2>(); foreach (object f in (object[])b.GetFaces()) l.Add((Face2)f); return l; }
    // faces of a body that are not planar faces lying at the given coordinate on the given axis (contact faces)
    static object[] Convect(Body2 b, params double[][] excl)
    {
        var l = new List<object>();
        foreach (Face2 f in FacesOf(b))
        {
            bool skip = false; Surface s = (Surface)f.GetSurface();
            if (s.IsPlane())
            {
                double[] n = (double[])f.Normal; double[] bx = (double[])f.GetBox();
                foreach (double[] e in excl)
                {   // e = {axis, coord}
                    int ax = (int)e[0];
                    if (Math.Abs(Math.Abs(n[ax]) - 1) < 1e-6 && Math.Abs(bx[ax] - e[1]) < 2e-4 && Math.Abs(bx[ax + 3] - e[1]) < 2e-4) skip = true;
                }
            }
            if (!skip) l.Add(f);
        }
        return l.ToArray();
    }
    static void Save(ModelDoc2 d, string name) { int e = 0, w = 0; d.Extension.SaveAs(Path.Combine(Out, name + ".SLDPRT"), 0, 1, null, ref e, ref w); }

    // ---------------- simulation helpers ----------------
    static CWStudy NewStudy(string name, bool transient)
    {
        int err; CWStudy st = cw.ActiveDoc.StudyManager.CreateNewStudy3(name, 3, 0, out err);
        if (st == null) throw new Exception("study create failed " + err);
        st.ThermalStudyOptions.SolutionType = transient ? 0 : 1;   // swsThermalSolutionType_e: 0 transient, 1 steady
        return st;
    }
    static CWSolidBody SolidBody(CWStudy st, string name)
    {
        int err; CWSolidBody b = st.SolidManager.GetSolidBodyByName(name, out err);
        if (b == null) { CWSolidComponent c = st.SolidManager.GetComponentAt(0, out err);
            for (int i = 0; i < c.SolidBodyCount; i++) { CWSolidBody x = c.GetSolidBodyAt(i, out err); if (x.SolidBodyName.Contains(name)) return x; }
            throw new Exception("solid body not in study: " + name); }
        return b;
    }
    // custom isotropic thermal material: k [W/mK], cp [J/kgK], rho [kg/m3]
    static void Mat(CWStudy st, string body, string label, double k, double cp, double rho)
    {
        CWSolidBody b = SolidBody(st, body);
        CWMaterial m = b.GetDefaultMaterial(); m.MaterialUnits = 0; m.MaterialName = label;
        m.SetPropertyByName("KX", k, 0); m.SetPropertyByName("C", cp, 0); m.SetPropertyByName("DENS", rho, 0);
        m.SetPropertyByName("EX", 1e9, 0); m.SetPropertyByName("NUXY", 0.3, 0);
        int r = b.SetSolidBodyMaterial(m); if (r != 0 && r != 1) Log("warning: material " + label + " returned " + r);
    }
    static void MatLib(CWStudy st, string body, string lib) { if (SolidBody(st, body).SetLibraryMaterial(Lib, lib) != 1) Log("warning: library material " + lib + " not applied to " + body); }
    static void Heat(CWStudy st, ModelDoc2 d, string body, double W, double[] curve)
    {
        int err; CWHeatPower hp = st.LoadsAndRestraintsManager.AddHeatPower(new object[] { Body(d, body) }, out err);
        if (hp == null) throw new Exception("heat power failed " + err);
        hp.HeatPowerBeginEdit(); hp.Unit = 0; hp.HPValue = W;
        if (st.ThermalStudyOptions.SolutionType == 0) { try { hp.IncludeThermostat2 = false; } catch (Exception) { hp.IncludeThermostat = 0; } }   // transient only: the flag is invalid in a steady study (end-edit error 8)
        if (curve != null) { int e2; object[] oc = Array.ConvertAll(curve, x => (object)x); int r = hp.SetTimeCurve(oc, out e2); Log("heat time curve " + body + ": r=" + r + " err=" + e2 + " use=" + hp.UseTimeCurve); if (e2 != 0) throw new Exception("time curve rejected " + e2); }
        int e = hp.HeatPowerEndEdit(); if (e != 0) throw new Exception("heat power end edit " + e);
    }
    static void Conv(CWStudy st, object[] faces, double h, double TambK, double[] curve)
    {
        if (faces.Length == 0) return;
        int err; CWConvection cv = st.LoadsAndRestraintsManager.AddConvection(faces, out err);
        if (cv == null) throw new Exception("convection failed " + err);
        cv.ConvectionBeginEdit(); cv.Unit = 0; cv.ConvectionCoefficient = h; cv.BulkAmbientTemperature = TambK;
        if (curve != null) { int e2; int r = cv.SetTimeCurve(curve, out e2); Log("convection time curve: r=" + r + " err=" + e2); }
        int e = cv.ConvectionEndEdit(); if (e != 0) throw new Exception("convection end edit " + e);
    }
    static void Initial(CWStudy st, ModelDoc2 d, double TK)
    {
        int err; var bodies = new List<object>(); foreach (Body2 b in Bodies(d)) bodies.Add(b);
        CWTemperature t = st.LoadsAndRestraintsManager.AddTemperature(bodies.ToArray(), out err);
        if (t == null) throw new Exception("initial temperature failed " + err);
        t.TemperatureBeginEdit(); t.TemperatureType = 0; t.Unit = 0; t.TemperatureValue = TK;
        int e = t.TemperatureEndEdit(); if (e != 0) throw new Exception("initial temperature end edit " + e);
    }
    static void Transient(CWStudy st, double total, double dt)
    {
        CWThermalStudyOptions o = st.ThermalStudyOptions; o.SolutionType = 0; o.TotalTime = total; o.TimeIncrement = dt;
        CWStudyResultOptions ro = st.StudyResultOptions;
        if (ro != null) { ro.SaveResultsForSolutionStepsOption = 0; }   // swsSaveResultsOption_ForAllSolutionSteps
    }
    static void Mesh(CWStudy st, double size)
    {
        CWMesh m = st.Mesh; m.Quality = 1;
        int r = st.CreateMesh(2, size, size * 0.05);
        if (r != 0) throw new Exception("mesh failed " + r);
    }
    static void Run(CWStudy st) { int r = st.RunAnalysis(); if (r != 0) throw new Exception("analysis failed " + r); }
    static double[] MinMax(CWStudy st, int step)
    {
        int e; object[] v = (object[])st.Results.GetMinMaxThermal(0, step, null, 2, out e);
        if (v == null) throw new Exception("GetMinMaxThermal failed " + e + " step " + step);
        return new double[] { Convert.ToDouble(v[1]), Convert.ToDouble(v[3]), Convert.ToDouble(v[0]), Convert.ToDouble(v[2]) };   // Tmin, Tmax, nodeMin, nodeMax
    }

    // ---------------- field export: nodes, surface triangles, nodal temperatures ----------------
    static double[] Nodes(CWStudy st, out int[] ids)
    {
        object o = st.Mesh.GetNodes(); double[] a = ToD(o);
        int n = a.Length / 4; var xyz = new double[3 * n]; ids = new int[n];
        for (int i = 0; i < n; i++) { ids[i] = (int)a[4 * i]; xyz[3 * i] = a[4 * i + 1]; xyz[3 * i + 1] = a[4 * i + 2]; xyz[3 * i + 2] = a[4 * i + 3]; }
        return xyz;
    }
    static double[] ToD(object o)
    {
        if (o == null || o is DBNull) return new double[0];
        if (o is double[]) return (double[])o;
        if (o is float[]) { float[] fa = (float[])o; var rf = new double[fa.Length]; for (int i = 0; i < fa.Length; i++) rf[i] = fa[i]; return rf; }
        if (o is int[]) { int[] ia = (int[])o; var ri = new double[ia.Length]; for (int i = 0; i < ia.Length; i++) ri[i] = ia[i]; return ri; }
        if (!(o is object[])) { Log("ToD: unexpected type " + o.GetType()); return new double[0]; }
        object[] arr = (object[])o; var r = new double[arr.Length]; for (int i = 0; i < arr.Length; i++) r[i] = Convert.ToDouble(arr[i]); return r;
    }
    static Dictionary<int, double> Temps(CWStudy st, int step)
    {
        int e; object o = null;
        // GetThermalValues(component, selection, units, err) returns the last solved step; for earlier steps use a plot
        // GetThermalValues(stepNo, selection, units): 10 values per node [node, T, gradX, gradY, gradZ, gradN, fluxX, fluxY, fluxZ, fluxN] (probed 2026-10-25)
        o = st.Results.GetThermalValues(step <= 0 ? 1 : step, null, 2, out e);
        double[] a = ToD(o); if (a.Length == 0) throw new Exception("GetThermalValues failed err " + e + " step " + step);
        int nn = st.Mesh.NodeCount, stride = nn > 0 && a.Length % nn == 0 ? a.Length / nn : 10;
        var m = new Dictionary<int, double>();
        for (int i = 0; i + 1 < a.Length; i += stride) m[(int)a[i]] = a[i + 1];
        return m;
    }
    static string Head(double[] a, int n) { return string.Join(",", new List<double>(a).GetRange(0, Math.Min(n, a.Length)).ConvertAll(x => x.ToString("G5", IC)).ToArray()); }
    static int[] Elements(CWStudy st) { double[] a = ToD(st.Mesh.GetElements()); var r = new int[a.Length]; for (int i = 0; i < a.Length; i++) r[i] = (int)a[i]; return r; }

    // write the surface mesh + temperatures as JSON: nodes [x,y,z...] (m), tris [i,j,k...] (0-based into nodes), T[case][step] per node
    static void WriteField(string name, CWStudy st, Dictionary<string, Dictionary<int, double>> fields, Dictionary<string, string> bodyOfNode)
    {
        int[] ids; double[] xyz = Nodes(st, out ids);
        var idx = new Dictionary<int, int>(); for (int i = 0; i < ids.Length; i++) idx[ids[i]] = i;
        int[] el = Elements(st);
        // GetElements layout: per element [elemNo, node1..nodeN] with N = 10 for 2nd-order tets (quality 1); detect stride
        int ne = st.Mesh.ElementCount, stride = ne > 0 && el.Length % ne == 0 ? el.Length / ne : 16;   // probed: 16 per element [id, n1..n10, cx, cy, cz, ..]
        var faceCount = new Dictionary<string, int[]>();
        int[][] tetFaces = { new[] { 0, 1, 2 }, new[] { 0, 1, 3 }, new[] { 1, 2, 3 }, new[] { 0, 2, 3 } };
        for (int e = 0; e + stride <= el.Length; e += stride)
        {
            int[] c = { el[e + 1], el[e + 2], el[e + 3], el[e + 4] };
            foreach (int[] f in tetFaces)
            {
                int[] t = { c[f[0]], c[f[1]], c[f[2]] }; Array.Sort(t); string k = t[0] + "," + t[1] + "," + t[2];
                if (faceCount.ContainsKey(k)) faceCount[k][3]++; else faceCount[k] = new[] { c[f[0]], c[f[1]], c[f[2]], 1 };
            }
        }
        var sb = new StringBuilder(); sb.Append("{\"name\":\"" + name + "\",\"nodes\":[");
        for (int i = 0; i < ids.Length; i++) { if (i > 0) sb.Append(','); sb.Append(xyz[3 * i].ToString("G6", IC)).Append(',').Append(xyz[3 * i + 1].ToString("G6", IC)).Append(',').Append(xyz[3 * i + 2].ToString("G6", IC)); }
        sb.Append("],\"tris\":["); bool first = true; int nt = 0;
        foreach (var kv in faceCount) if (kv.Value[3] == 1 && idx.ContainsKey(kv.Value[0]) && idx.ContainsKey(kv.Value[1]) && idx.ContainsKey(kv.Value[2]))
            { if (!first) sb.Append(','); first = false; sb.Append(idx[kv.Value[0]]).Append(',').Append(idx[kv.Value[1]]).Append(',').Append(idx[kv.Value[2]]); nt++; }
        sb.Append("],\"fields\":{"); bool f1 = true;
        foreach (var kv in fields)
        {
            if (!f1) sb.Append(','); f1 = false; sb.Append("\"" + kv.Key + "\":[");
            for (int i = 0; i < ids.Length; i++) { if (i > 0) sb.Append(','); double t; sb.Append(kv.Value.TryGetValue(ids[i], out t) ? t.ToString("G5", IC) : "null"); }
            sb.Append(']');
        }
        sb.Append("}");
        if (bodyOfNode != null) { sb.Append(",\"body\":["); for (int i = 0; i < ids.Length; i++) { if (i > 0) sb.Append(','); string bn; sb.Append(bodyOfNode.TryGetValue(ids[i].ToString(), out bn) ? "\"" + bn + "\"" : "null"); } sb.Append(']'); }
        sb.Append("}");
        File.WriteAllText(Path.Combine(Out, "fields", name + ".json"), sb.ToString());
        Log("field " + name + ": " + ids.Length + " nodes, " + nt + " surface triangles, stride " + stride);
    }
    // node -> body name via the mesh node lists of each body's faces
    static Dictionary<string, string> BodyMap(CWStudy st, ModelDoc2 d)
    {
        var m = new Dictionary<string, string>();
        foreach (Body2 b in Bodies(d))
        {
            foreach (Face2 f in FacesOf(b))
            {
                int err; object o = st.Mesh.GetNodeDataFromEntity(f, out err); if (o == null) continue;
                double[] a = ToD(o);   // [node, x, y, z] per node (assumed; checked by Probe)
                int stride = a.Length % 4 == 0 ? 4 : 1;
                for (int i = 0; i < a.Length; i += stride) { string k = ((int)a[i]).ToString(); if (!m.ContainsKey(k)) m[k] = b.Name; }
            }
        }
        return m;
    }
    // per-body max temperature from a field
    static Dictionary<string, double> BodyMax(Dictionary<int, double> T, Dictionary<string, string> bodyOf)
    {
        var r = new Dictionary<string, double>();
        foreach (var kv in T) { string b; if (!bodyOf.TryGetValue(kv.Key.ToString(), out b)) continue; double cur; if (!r.TryGetValue(b, out cur) || kv.Value > cur) r[b] = kv.Value; }
        return r;
    }
    static int HotNode(Dictionary<int, double> T, Dictionary<string, string> bodyOf, string body)
    {
        int best = -1; double bv = -1e9;
        foreach (var kv in T) { string b; if (bodyOf.TryGetValue(kv.Key.ToString(), out b) && b == body && kv.Value > bv) { bv = kv.Value; best = kv.Key; } }
        return best;
    }
    // temperature history at the hottest node of a body: GetThermalComponentForAllStepsAtNode(component, node, selection, units)
    static double[] History(CWStudy st, int node)
    {
        int e; object o = st.Results.GetThermalComponentForAllStepsAtNode(0, node, null, 2, out e);
        if (o == null) throw new Exception("history failed " + e);
        return ToD(o);
    }
    static double[] StepTimes(CWStudy st)
    {
        int e; object o = st.Results.GetTimeOrFrequencyAtEachStep(0, out e); double[] r = ToD(o);
        if (r.Length == 0) { try { o = st.Results.GetTimeOrFrequencyAtEachStep2(true, out e); r = ToD(o); } catch (Exception) { } }
        if (r.Length == 0) { try { o = st.Results.GetTimeOrFrequencyAtEachStep(1, out e); r = ToD(o); } catch (Exception) { } }
        if (r.Length == 0) { double dt = st.ThermalStudyOptions.TimeIncrement; int n = st.Results.GetMaximumAvailableSteps(); r = new double[n]; for (int i = 0; i < n; i++) r[i] = dt * (i + 1); Log("step times reconstructed from TimeIncrement " + dt); }
        return r;
    }
    static void PlotPng(ModelDoc2 d, CWStudy st, string file)
    {
        int e; CWPlot p = st.Results.GetPlot("Thermal1", out e);
        if (p != null) { p.ActivatePlot(); d.ShowNamedView2("*Isometric", -1); d.ViewZoomtofit2(); int er = 0, w = 0; d.Extension.SaveAs(Path.Combine(Out, file), 0, 1, null, ref er, ref w); }
    }

    // ---------------- probe: API behaviour on the simple motor cylinder (kept short; see docs/research/thermal.md "API notes") ----------------
    static void Probe()
    {
        double dia = D("motorD"), h = D("motorH");
        ModelDoc2 d = NewPart();
        Sk(d, "Top Plane"); Circ(d, 0, 0, dia / 2); EndSk(d); Ext(d, 1, 0, h, true, "Motor");
        Save(d, "PROBE_Motor");
        CWStudy ss = NewStudy("probe transient", true);
        MatLib(ss, "Motor", P["matLib"]);
        Heat(ss, d, "Motor", D("thermQ"), null);
        Conv(ss, Convect(Body(d, "Motor")), D("thermH"), D("thermAmbK"), null);
        Initial(ss, d, D("thermAmbK"));
        Transient(ss, 90, 5); Mesh(ss, 0.004); Run(ss);
        Log("steps available: " + ss.Results.GetMaximumAvailableSteps() + " (expected 18)");
        CWStudy s3 = NewStudy("probe chain", true);
        MatLib(s3, "Motor", P["matLib"]); Heat(s3, d, "Motor", 0.0, null);
        Conv(s3, Convect(Body(d, "Motor")), D("thermH"), D("thermAmbK"), null);
        ChainFrom(s3, "probe transient", 18);
        Transient(s3, 60, 5); Mesh(s3, 0.004); Run(s3);
        Log("chain step 1 Tmax " + MinMax(s3, 1)[1].ToString("F2", IC) + " (expected ~60, the 90 s value of the first study)");
        Save(d, "PROBE_Motor");
        sw.CloseDoc(d.GetTitle());
    }
    static void ChainFrom(CWStudy st, string prev, int step)
    {
        CWThermalStudyOptions o = st.ThermalStudyOptions;
        try { o.UseTemperatureFromThermalStudy2 = true; } catch (Exception) { o.UseTemperatureFromThermalStudy = 1; }
        o.ThermalStudyNameUsedForInitialTemperature = prev; o.TimeSteps = step;   // TimeSteps = step of `prev` taken as the initial field (probed 2026-10-25)
    }

    // ---------------- chained transient mission: one study per phase, initial field = last step of the previous phase ----------------
    class Phase { public string name; public double dur, dt; public Phase(string n, double du, double t) { name = n; dur = du; dt = t; } }
    // setup(study, phase) applies materials, heat loads and convection for that phase. Returns per-body max history [t, T...] and fills fields at phase ends.
    static Dictionary<string, List<double[]>> Chain(ModelDoc2 d, string prefix, List<Phase> phases, Action<CWStudy, Phase> setup, string[] bodies,
        double TambK, double meshSize, Dictionary<string, Dictionary<int, double>> fields, string[] fieldAtEnd, out Dictionary<string, string> bodyOf, out CWStudy last)
    {
        var hist = new Dictionary<string, List<double[]>>(); foreach (string b in bodies) hist[b] = new List<double[]>();
        string prev = null; int prevSteps = 0; double t0 = 0; bodyOf = null; last = null;
        int k = 0;
        foreach (Phase ph in phases)
        {
            string name = prefix + " " + (++k) + " " + ph.name;
            CWStudy st = NewStudy(name, true); setup(st, ph);
            if (prev == null) Initial(st, d, TambK); else ChainFrom(st, prev, prevSteps);
            Transient(st, ph.dur, ph.dt); Mesh(st, meshSize); Run(st);
            int n = st.Results.GetMaximumAvailableSteps();
            Log("  " + name + ": " + n + " steps");
            if (bodyOf == null) bodyOf = BodyMap(st, d);
            // body-max history from the hottest node of each body at the start and at the end of the phase (GetThermalComponentForAllStepsAtNode:
            // [step, time, T] per step), instead of one full-field call per step
            var Tend = Temps(st, n); var T1 = Temps(st, 1);
            foreach (string b in bodies)
            {
                var cand = new List<int>(); foreach (var T in new[] { Tend, T1 }) { int hn = HotNode(T, bodyOf, b); if (hn > 0 && !cand.Contains(hn)) cand.Add(hn); }
                var rows = new List<double[]>();
                foreach (int node in cand) { double[] hs = History(st, node); for (int s = 0; s * 3 + 2 < hs.Length; s++) { if (rows.Count <= s) rows.Add(new[] { t0 + hs[s * 3 + 1], hs[s * 3 + 2] }); else rows[s][1] = Math.Max(rows[s][1], hs[s * 3 + 2]); } }
                hist[b].AddRange(rows);
            }
            if (Array.IndexOf(fieldAtEnd, ph.name + k) >= 0) fields["end_" + ph.name + k] = Tend;
            if (Array.IndexOf(fieldAtEnd, ph.name) >= 0) fields["end_" + ph.name] = Tend;
            t0 += ph.dur; prev = name; prevSteps = n; last = st;
        }
        return hist;
    }
    // mission phases from the t_end_* keys (the flat JSON reader does not index arrays)
    static List<Phase> MissionPhases()
    {
        double h1 = I("mission.t_end_hover1_s"), tr1 = I("mission.t_end_trans1_s") - h1, cr = I("mission.t_end_cruise_s") - I("mission.t_end_trans1_s"), tr2 = I("mission.t_end_trans2_s") - I("mission.t_end_cruise_s"), h2 = I("mission.total_s") - I("mission.t_end_trans2_s");
        return new List<Phase> { new Phase("hover", h1, 5), new Phase("transition", tr1, 5), new Phase("cruise", cr, 20), new Phase("transition", tr2, 5), new Phase("hover", h2, 5) };
    }
    static void WriteHistory(string file, Dictionary<string, List<double[]>> hist)
    {
        var sb = new StringBuilder("{"); bool first = true;
        foreach (var kv in hist)
        {
            if (!first) sb.Append(','); first = false;
            sb.Append("\"" + kv.Key + "\":{\"t\":[" + string.Join(",", kv.Value.ConvertAll(x => x[0].ToString("G6", IC)).ToArray()) + "],\"T\":[" + string.Join(",", kv.Value.ConvertAll(x => x[1].ToString("G5", IC)).ToArray()) + "]}");
        }
        sb.Append("}"); File.WriteAllText(Path.Combine(Out, "fields", file), sb.ToString());
    }
    static double HistMax(Dictionary<string, List<double[]>> hist, string body) { double m = -1e9; foreach (double[] x in hist[body]) m = Math.Max(m, x[1]); return m; }
    static double HistAt(Dictionary<string, List<double[]>> hist, string body, double t) { double best = double.NaN, bd = 1e9; foreach (double[] x in hist[body]) if (Math.Abs(x[0] - t) < bd) { bd = Math.Abs(x[0] - t); best = x[1]; } return best; }

    // ---------------- study M: motor-only (validation against cad/Sim.cs 141 C steady and the 76 C lumped 90 s value) ----------------
    static void MotorOnly()
    {
        double dia = D("motorD"), h = D("motorH"), Q = I("loads.lift_motor_W"), hh = I("h.motor_hover"), Tamb = I("ambient.hot_K");
        ModelDoc2 d = NewPart();
        Sk(d, "Top Plane"); Circ(d, 0, 0, dia / 2); EndSk(d); Ext(d, 1, 0, h, true, "Motor");
        Save(d, "THERM_Motor_Only");
        double A = Math.PI * dia * h + 2 * Math.PI * dia * dia / 4;
        // (a) same inputs as cad/Sim.cs Thermal(): thermQ, thermH = 50, 6061 library -> reproduces results.txt motor_T_steady
        CWStudy ss = NewStudy("Motor steady Sim-cs inputs", false);
        MatLib(ss, "Motor", P["matLib"]); Heat(ss, d, "Motor", D("thermQ"), null); Conv(ss, Convect(Body(d, "Motor")), D("thermH"), D("thermAmbK"), null);
        Mesh(ss, 0.004); Run(ss);
        Res("val_simcs_T_steady", MinMax(ss, 1)[1], "degC", "motor-only steady with cad/Sim.cs inputs (thermQ " + P["thermQ"] + " W, h " + P["thermH"] + "), compare cad/sim/results.txt motor_T_steady");
        Res("val_simcs_T_hand", D("thermAmbK") - 273.15 + D("thermQ") / (D("thermH") * A), "degC", "hand: T_amb + Q/(h A), A = " + A.ToString("G4", IC) + " m2");
        // (b) this analysis' inputs: Q from results.json, h from the Hilpert correlation at v_i, lumped motor material
        CWStudy s2 = NewStudy("Motor steady correlation h", false);
        Mat(s2, "Motor", "motor lump (est.)", I("materials.motor.k"), I("materials.motor.cp"), I("materials.motor.rho"));
        Heat(s2, d, "Motor", Q, null); Conv(s2, Convect(Body(d, "Motor")), hh, Tamb, null);
        Mesh(s2, 0.004); Run(s2);
        Res("motor_only_T_steady", MinMax(s2, 1)[1], "degC", "motor-only steady, Q " + Q.ToString("G4", IC) + " W, h " + hh.ToString("G4", IC) + " W/m2K (Hilpert at v_i), 35 C");
        Res("motor_only_T_hand", Tamb - 273.15 + Q / (hh * A), "degC", "hand: T_amb + Q/(h A)");
        // (c) transient 90 s with the lumped motor material (cp 470): compare review/src/app.js TH.T90 (76 C with Sim.cs inputs)
        CWStudy tr = NewStudy("Motor transient 90 s Sim-cs inputs", true);
        Mat(tr, "Motor", "motor lump (est.)", I("materials.motor.k"), I("materials.motor.cp"), I("materials.motor.rho"));
        Heat(tr, d, "Motor", D("thermQ"), null); Conv(tr, Convect(Body(d, "Motor")), D("thermH"), D("thermAmbK"), null); Initial(tr, d, D("thermAmbK"));
        Transient(tr, 90, 5); Mesh(tr, 0.004); Run(tr);
        int n = tr.Results.GetMaximumAvailableSteps();
        Res("val_motor_steps", n, "-", "transient steps saved (API: initial temperature load + SaveResultsForSolutionStepsOption; see docs/research/thermal.md)");
        double tau = I("materials.motor.cp") * D("motorMass") / (D("thermH") * A), dT = D("thermQ") / (D("thermH") * A);
        Res("val_motor_T90", MinMax(tr, n)[1], "degC", "motor-only 90 s FEA, cp 470 J/kgK, Sim.cs inputs");
        Res("val_motor_T90_lumped", D("thermAmbK") - 273.15 + dT * (1 - Math.Exp(-90 / tau)), "degC", "lumped T_amb + dT (1 - exp(-t/tau)), tau " + tau.ToString("G4", IC) + " s (review/src/app.js TH)");
        Save(d, "THERM_Motor_Only");
        sw.CloseDoc(d.GetTitle());
    }

    // ---------------- study L: lift unit = motor + PA6-CF mount + boom + ESC on its foam pad ----------------
    // local frame: boom axis X, up Y. Mount block 70 (X) x 46 (Z) from y -15 to +21 over the boom (bore 25.6); motor on the mount top;
    // ESC under the boom ahead of the mount on a 3 mm pad.
    static void LiftUnit()
    {
        double dia = D("motorD"), hm = D("motorH"), od = D("boomOD"), id = D("boomID");
        double mountL = I("mount.len_m"), mountW = I("mount.width_m"), mountTop = I("mount.top_m"), mountBot = I("mount.bot_m"), bore = I("mount.bore_m") / 2;
        double boomL = I("boom.segment_m"), escL = I("esc.len_m"), escW = I("esc.width_m"), escH = I("esc.height_m"), padT = I("esc.pad_m"), escX = I("esc.x_m");
        double Tamb = I("ambient.hot_K"), fTrans = I("loads.lift_motor_trans_W") / I("loads.lift_motor_W");
        ModelDoc2 d = NewPart();
        Sk(d, "Right Plane"); Circ(d, 0, 0, od / 2); Circ(d, 0, 0, id / 2); EndSk(d); Ext(d, 0, -boomL / 2, boomL / 2, false, "Boom");
        Sk(d, "Right Plane"); Rect(d, -mountW / 2, -mountBot, mountW / 2, mountTop); Circ(d, 0, 0, bore); EndSk(d); Ext(d, 0, -mountL / 2, mountL / 2, false, "Mount");
        Sk(d, "Top Plane"); Circ(d, 0, 0, dia / 2); EndSk(d); Ext(d, 1, mountTop, mountTop + hm, false, "Motor");
        Sk(d, "Top Plane"); Rect(d, escX - escL / 2, -escW / 2, escX + escL / 2, escW / 2); EndSk(d); Ext(d, 1, -(od / 2 + padT), -od / 2, false, "Pad");
        Sk(d, "Top Plane"); Rect(d, escX - escL / 2, -escW / 2, escX + escL / 2, escW / 2); EndSk(d); Ext(d, 1, -(od / 2 + padT + escH), -(od / 2 + padT), false, "ESC");
        Save(d, "THERM_Lift_Unit");
        string[] bodies = { "Motor", "Mount", "Boom", "ESC", "Pad" };
        Action<CWStudy, string> setup = (st, ph) =>
        {
            bool cruise = ph == "cruise"; double fQ = ph == "hover" ? 1 : ph == "transition" ? fTrans : 0; string sfx = cruise ? "_cruise" : "_hover";
            Mat(st, "Boom", "6061-T6 (library values)", I("materials.al6061.k"), I("materials.al6061.cp"), I("materials.al6061.rho"));   // custom copy of the library values: the library material raises a modal "Plasticity - von Mises invalid, switching to Linear Elastic" warning in thermal studies that blocks the API
            Mat(st, "Motor", "motor lump (est.)", I("materials.motor.k"), I("materials.motor.cp"), I("materials.motor.rho"));
            Mat(st, "Mount", "PA6-CF (est.)", I("materials.pa6cf.k"), I("materials.pa6cf.cp"), I("materials.pa6cf.rho"));
            Mat(st, "Pad", "foam pad (est.)", I("materials.foam.k"), I("materials.foam.cp"), I("materials.foam.rho"));
            Mat(st, "ESC", "ESC lump (est.)", I("materials.esc.k"), I("materials.esc.cp"), I("materials.esc.rho"));
            Heat(st, d, "Motor", fQ * I("loads.lift_motor_W"), null);
            Heat(st, d, "ESC", fQ * I("loads.lift_esc_W"), null);
            Conv(st, Convect(Body(d, "Motor"), new[] { 1.0, mountTop }), I("h.motor" + sfx), Tamb, null);
            Conv(st, Convect(Body(d, "Mount"), new[] { 1.0, mountTop }), I("h.mount" + sfx), Tamb, null);
            Conv(st, Convect(Body(d, "Boom")), I("h.boom" + sfx), Tamb, null);
            Conv(st, Convect(Body(d, "ESC"), new[] { 1.0, -(od / 2 + padT) }), I("h.esc" + sfx), Tamb, null);
        };
        var fields = new Dictionary<string, Dictionary<int, double>>();
        // steady hover (upper bound)
        CWStudy ss = NewStudy("Lift unit steady hover", false); setup(ss, "hover"); Mesh(ss, 0.004); Run(ss);
        var bodyOf = BodyMap(ss, d); var T0 = Temps(ss, 0); fields["steady_hover"] = T0;
        foreach (var kv in BodyMax(T0, bodyOf)) Res("lift_steady_" + kv.Key, kv.Value, "degC", "lift unit steady hover, 35 C, max in body");
        PlotPng(d, ss, "THERM_Lift_Unit_steady.png");
        // hover transient 0..120 s (bench C08 is 90 s; test-plan hover-only flights <= 60 s)
        Dictionary<string, string> bo; CWStudy lastSt;
        var hov = Chain(d, "Lift hover", new List<Phase> { new Phase("hover", I("mission.hover_transient_s"), 5) }, (st, ph) => setup(st, ph.name), bodies, Tamb, 0.004, fields, new string[0], out bo, out lastSt);
        int nh = lastSt.Results.GetMaximumAvailableSteps();
        foreach (double tw in new[] { 30.0, 60.0, 90.0, 120.0 }) { int s = (int)Math.Round(tw / 5); if (s >= 1 && s <= nh) fields["hover_" + (int)tw + "s"] = Temps(lastSt, s); }
        foreach (string b in bodies) foreach (double tw in new[] { 30.0, 60.0, 90.0, 120.0 }) Res("lift_hover" + (int)tw + "_" + b, HistAt(hov, b, tw), "degC", "lift unit hover transient from 35 C, max in body");
        WriteHistory("lift_unit_hover_history.json", hov);
        // mission chain: hover 60 - transition 20 - cruise 600 (lift motors stopped, 20 m/s cooling) - transition 20 - hover 60
        var phases = new List<Phase>();
        foreach (Phase ph in MissionPhases()) phases.Add(ph);
        var mis = Chain(d, "Lift mission", phases, (st, ph) => setup(st, ph.name), bodies, Tamb, 0.004, fields, new[] { "hover1", "transition2", "hover5" }, out bo, out lastSt);
        foreach (string b in bodies) { Res("lift_mission_max_" + b, HistMax(mis, b), "degC", "lift unit mission peak, hot day 35 C"); Res("lift_mission_end_" + b, HistAt(mis, b, I("mission.total_s")), "degC", "lift unit at mission end (after the landing hover)"); }
        WriteHistory("lift_unit_mission_history.json", mis);
        WriteField("lift_unit", lastSt, fields, bo);
        Save(d, "THERM_Lift_Unit");
        sw.CloseDoc(d.GetTitle());
    }

    // ---------------- study P: pod = XPS foam body with battery bay + avionics bay, hot-day mission ----------------
    // local frame: pod axis X (cylinder radius fusR, length fusL), up Y; pod local = global - (0.45, yPod, 0) (cad/params.mjs)
    static void Pod()
    {
        double L = D("fusL"), Rr = D("fusR"), bL = D("battL"), bH = D("battH"), bW = D("battW");
        double fcL = I("fc.len_m"), fcW = I("fc.width_m"), fcH = I("fc.height_m");
        double bayY0 = D("bayY0") - D("yPod"), bayY1 = D("bayY1") - D("yPod"), bayZ = D("bayZ");
        double bx = D("battX") - 0.45, bayX0 = D("bayX0") - 0.45, bayX1 = D("bayX1") - 0.45, fx = 0.225 - 0.45;
        double bl = bL / 2 + 0.005, bayBot = -0.080 - D("yPod");   // BuildVtol.cs Fuselage(): battery bay from y = -0.080 (global) 60 mm up, 60 wide
        double Tamb = I("ambient.hot_K");
        ModelDoc2 d = NewPart();
        Sk(d, "Right Plane"); Circ(d, 0, 0, Rr); EndSk(d); Ext(d, 0, -L / 2, L / 2, false, "FoamBody");   // a body takes the name of the last feature that modifies it, so the last cut is named "Foam"
        Sk(d, "Top Plane"); Rect(d, bx - bl, -0.030, bx + bl, 0.030); EndSk(d); CutRange(d, 1, bayBot, bayBot + 0.060, "battery bay");
        Sk(d, "Top Plane"); Rect(d, bayX0, -bayZ, bayX1, bayZ); EndSk(d); CutRange(d, 1, bayY0, bayY1, "Foam");
        Sk(d, "Top Plane"); Rect(d, bx - bL / 2, -bW / 2, bx + bL / 2, bW / 2); EndSk(d); Ext(d, 1, bayBot + 0.003, bayBot + 0.003 + bH, false, "Battery");
        Sk(d, "Top Plane"); Rect(d, fx - fcL / 2, -fcW / 2, fx + fcL / 2, fcW / 2); EndSk(d); Ext(d, 1, bayY0 + 0.003, bayY0 + 0.003 + fcH, false, "FC");
        Save(d, "THERM_Pod");
        foreach (Body2 b in Bodies(d)) Log("  " + Box(b));
        string[] bodies = { "Battery", "FC", "Foam" };
        Action<CWStudy, string> setup = (st, ph) =>
        {
            Mat(st, "Foam", "XPS (est.)", I("materials.xps.k"), I("materials.xps.cp"), I("materials.xps.rho"));
            Mat(st, "Battery", "LiPo pack (est.)", I("materials.lipo.k"), I("materials.lipo.cp"), I("materials.lipo.rho"));
            Mat(st, "FC", "FC lump (est.)", I("materials.esc.k"), I("materials.esc.cp"), I("materials.esc.rho"));
            Heat(st, d, "Battery", I("loads.batt_" + (ph == "hover" ? "hover" : ph == "transition" ? "trans" : "cruise") + "_W"), null);
            Heat(st, d, "FC", I("loads.fc_W"), null);
            Conv(st, Convect(Body(d, "Foam")), I(ph == "cruise" ? "h.pod_cruise" : "h.pod_hover"), Tamb, null);
            // battery and FC faces that see bay air: natural convection to air at ambient (EST; the closed bay air warms in reality, so this is optimistic for the top faces and offset by the adiabatic foam sides)
            Conv(st, Convect(Body(d, "Battery"), new[] { 1.0, bayBot + 0.003 }), I("h.bay_natural"), Tamb, null);
            Conv(st, Convect(Body(d, "FC"), new[] { 1.0, bayY0 + 0.003 }), I("h.bay_natural"), Tamb, null);
        };
        var fields = new Dictionary<string, Dictionary<int, double>>();
        var phases = new List<Phase>();
        foreach (Phase ph in MissionPhases()) phases.Add(ph);
        Dictionary<string, string> bo; CWStudy lastSt;
        var mis = Chain(d, "Pod mission", phases, (st, ph) => setup(st, ph.name), bodies, Tamb, 0.010, fields, new[] { "hover1", "transition2", "cruise3", "hover5" }, out bo, out lastSt);
        foreach (string b in bodies) { Res("pod_mission_max_" + b, HistMax(mis, b), "degC", "pod hot-day mission peak, max in body"); Res("pod_mission_end_" + b, HistAt(mis, b, I("mission.total_s")), "degC", "pod at mission end"); }
        WriteHistory("pod_mission_history.json", mis);
        WriteField("pod", lastSt, fields, bo);
        PlotPng(d, lastSt, "THERM_Pod_mission.png");
        Save(d, "THERM_Pod");
        sw.CloseDoc(d.GetTitle());
    }

    // ---------------- study K: pusher motor in the PA6-CF cup in the pod tail, cruise ----------------
    static void Pusher()
    {
        double dia = D("pushMotorD"), hm = D("pushMotorL"), cupD = I("cup.od_m"), cupFloor = I("cup.floor_m"), cupWall = I("cup.wall_m"), cupLen = I("cup.len_m");
        double Tamb = I("ambient.hot_K");
        ModelDoc2 d = NewPart();
        Sk(d, "Right Plane"); Circ(d, 0, 0, cupD / 2); EndSk(d); Ext(d, 0, 0, cupFloor, false, "CupFloor");
        Sk(d, "Right Plane"); Circ(d, 0, 0, cupD / 2); Circ(d, 0, 0, cupD / 2 - cupWall); EndSk(d); Ext(d, 0, cupFloor, cupLen, false, "CupWall");
        Sk(d, "Right Plane"); Circ(d, 0, 0, dia / 2); EndSk(d); Ext(d, 0, cupFloor, cupFloor + hm, false, "Motor");
        Sk(d, "Right Plane"); Circ(d, 0, 0, I("cup.ring_od_m") / 2); Circ(d, 0, 0, cupD / 2); EndSk(d); Ext(d, 0, 0, cupLen, false, "Foam");
        Save(d, "THERM_Pusher");
        foreach (Body2 b in Bodies(d)) Log("  " + Box(b));
        string[] bodies = { "Motor", "CupFloor", "CupWall", "Foam" };
        Action<CWStudy> setup = st =>
        {
            Mat(st, "Motor", "pusher motor lump (est.)", I("materials.motor.k"), I("materials.motor.cp"), I("materials.pusher.rho"));
            Mat(st, "CupFloor", "PA6-CF (est.)", I("materials.pa6cf.k"), I("materials.pa6cf.cp"), I("materials.pa6cf.rho"));
            Mat(st, "CupWall", "PA6-CF (est.)", I("materials.pa6cf.k"), I("materials.pa6cf.cp"), I("materials.pa6cf.rho"));
            Mat(st, "Foam", "XPS (est.)", I("materials.xps.k"), I("materials.xps.cp"), I("materials.xps.rho"));
            Heat(st, d, "Motor", I("loads.pusher_motor_W"), null);
            Conv(st, Convect(Body(d, "Motor"), new[] { 0.0, cupFloor }), I("h.pusher_motor_cruise"), Tamb, null);
            Conv(st, Convect(Body(d, "CupWall"), new[] { 0.0, cupFloor }, new[] { 0.0, cupLen }), I("h.cup_inner_cruise"), Tamb, null);
            Conv(st, Convect(Body(d, "Foam"), new[] { 0.0, 0.0 }), I("h.pod_cruise"), Tamb, null);
        };
        var fields = new Dictionary<string, Dictionary<int, double>>();
        CWStudy ss = NewStudy("Pusher steady cruise", false); setup(ss); Mesh(ss, 0.003); Run(ss);
        var bodyOf = BodyMap(ss, d); var T0 = Temps(ss, 0); fields["steady_cruise"] = T0;
        foreach (var kv in BodyMax(T0, bodyOf)) Res("pusher_steady_" + kv.Key, kv.Value, "degC", "pusher steady cruise, 35 C, max in body");
        Dictionary<string, string> bo; CWStudy lastSt;
        var cr = Chain(d, "Pusher cruise", new List<Phase> { new Phase("cruise", I("mission.cruise_s"), 20) }, (st, ph) => setup(st), bodies, Tamb, 0.003, fields, new[] { "cruise" }, out bo, out lastSt);
        foreach (string b in bodies) Res("pusher_endcruise_" + b, HistAt(cr, b, I("mission.cruise_s")), "degC", "pusher after " + I("mission.cruise_s") + " s cruise from 35 C, max in body");
        WriteHistory("pusher_cruise_history.json", cr);
        WriteField("pusher", lastSt, fields, bo);
        PlotPng(d, ss, "THERM_Pusher_steady.png");
        Save(d, "THERM_Pusher");
        sw.CloseDoc(d.GetTitle());
    }
}
